  const pinComp = figma.createComponent();
  pinComp.name = "Marcador";
  pinComp.layoutMode = "HORIZONTAL";
  pinComp.primaryAxisAlignItems = "CENTER";
  pinComp.counterAxisAlignItems = "CENTER";
